package com.feimao.mapper;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;
import org.apache.ibatis.annotations.Insert;
import org.apache.ibatis.annotations.Options;
import org.apache.ibatis.annotations.Update;

@Mapper
public interface StoreWorkspaceMapper {
  @Select("select id,avatar,name,mobile,password,salt,status from ymcx_merchant where username=#{username} and is_delete=1 and deletetime is null and examine_status=2") Map<String,Object> loginMerchant(@Param("username") String username);
  @Select("select id from ymcx_merchant where id=#{id} and is_delete=1 and deletetime is null and status=1") Long activeMerchant(@Param("id") long id);
  @Select("select id,name,avatar,mobile,qrimage,money from ymcx_merchant where id=#{id} and is_delete=1 and deletetime is null") Map<String,Object> merchantHome(@Param("id") long id);
  @Select("select coalesce(sum(money),0) from ymcx_merchant_money_log where merchant_id=#{id} and type=1 and is_delete=1 and deletetime is null") BigDecimal orderIncome(@Param("id") long id);
  @Select("select count(*) from ymcx_merchant_money_log where merchant_id=#{id} and type=1 and is_delete=1 and deletetime is null") int moneyLogCount(@Param("id") long id);
  @Select("select ml.id,ml.money price,ml.createtime,o.number,u.nickname user_name,u.avatar user_avatar from ymcx_merchant_money_log ml left join ymcx_order o on o.id=ml.order_id left join ymcx_user u on u.id=o.user_id where ml.merchant_id=#{id} and ml.type=1 and ml.is_delete=1 and ml.deletetime is null order by ml.createtime desc limit #{limit} offset #{offset}") List<Map<String,Object>> moneyLogs(@Param("id") long id,@Param("limit") long limit,@Param("offset") long offset);
  @Select({"<script>select count(*) from ymcx_order o where o.is_delete=1 and o.merchant_id=#{id} and o.state in (2,3,4,5,6)<if test='state &gt; 0'>and o.state=#{state}</if><if test='pick &gt; 0'>and o.pick_type=#{pick}</if><if test='search != null and search != \"\"'>and (o.number like concat('%',#{search},'%') or o.mobile like concat('%',#{search},'%'))</if></script>"}) int orderCount(@Param("id") long id,@Param("state") int state,@Param("pick") int pick,@Param("search") String search);
  @Select({"<script>select o.id,o.number,o.user_id,o.merchant_id,o.merchant_car_id,o.order_name,o.service_name,o.service_image,o.pick_type,o.lease_type,o.lease_duration,o.price,o.cash_price,o.cash_state,o.pick_state,o.state,u.nickname user_name,u.avatar user_avatar,m.name merchant_name,m.address merchant_address,m.administrative merchant_administrative from ymcx_order o left join ymcx_user u on u.id=o.user_id left join ymcx_merchant m on m.id=o.merchant_id and m.deletetime is null where o.is_delete=1 and o.merchant_id=#{id} and o.state in (2,3,4,5,6)<if test='state &gt; 0'>and o.state=#{state}</if><if test='pick &gt; 0'>and o.pick_type=#{pick}</if><if test='search != null and search != \"\"'>and (o.number like concat('%',#{search},'%') or o.mobile like concat('%',#{search},'%'))</if> order by o.createtime desc limit #{limit} offset #{offset}</script>"}) List<Map<String,Object>> orders(@Param("id") long id,@Param("state") int state,@Param("pick") int pick,@Param("search") String search,@Param("limit") long limit,@Param("offset") long offset);
  @Select("select o.*,m.name merchant_name,m.administrative merchant_administrative,m.business merchant_business,m.mobile merchant_mobile,m.address merchant_address,case when o.type=3 then coalesce(mt.introductory,'') else concat('车辆品牌:',coalesce(b.name,'')) end introductory from ymcx_order o join ymcx_merchant m on m.id=o.merchant_id and m.deletetime is null left join ymcx_merchant_maintain mm on mm.id=o.merchant_service_id and mm.deletetime is null left join ymcx_maintain mt on mt.id=mm.maintain_id and mt.deletetime is null left join ymcx_merchant_car mc on mc.id=o.merchant_car_id and mc.deletetime is null left join ymcx_platform_car pc on pc.id=mc.platform_car_id and pc.deletetime is null left join ymcx_brand b on b.id=pc.brand_id and b.deletetime is null where o.number=#{number} and o.merchant_id=#{merchantId}") Map<String,Object> order(@Param("number") String number,@Param("merchantId") long merchantId);
  @Select("select name,mobile,idcard from ymcx_order_guest where order_id=#{id} and is_delete=1 and deletetime is null order by id") List<Map<String,Object>> orderGuests(@Param("id") long id);
  @Select("select id,name,avatar,nickname,image,mobile,money,business,administrative,address,intro,pick_type,car_num,min_price,lat,lng,qrimage from ymcx_merchant where id=#{id} and is_delete=1 and deletetime is null") Map<String,Object> profile(@Param("id") long id);
  @Select("select count(*) from ymcx_merchant_car where merchant_id=#{merchantId} and is_delete=1 and deletetime is null and status=#{status}") int carCount(@Param("merchantId") long merchantId,@Param("status") int status);
  @Select("select mc.id,mc.platform_car_id,mc.intro,mc.images,mc.cash_price,mc.month_price,mc.day_price,mc.hour_price,mc.total_stock,mc.stock,p.name,p.image,p.brand_id,p.specification,b.name brand_name from ymcx_merchant_car mc join ymcx_platform_car p on p.id=mc.platform_car_id and p.deletetime is null left join ymcx_brand b on b.id=p.brand_id and b.deletetime is null where mc.merchant_id=#{merchantId} and mc.is_delete=1 and mc.deletetime is null and mc.status=#{status} order by mc.createtime desc limit #{limit} offset #{offset}") List<Map<String,Object>> cars(@Param("merchantId") long merchantId,@Param("status") int status,@Param("limit") long limit,@Param("offset") long offset);
  @Select("select id,name from ymcx_brand where is_delete=1 and deletetime is null and status=1 order by weigh desc") List<Map<String,Object>> brands();
  @Select({"<script>select id,name from ymcx_platform_car where is_delete=1 and deletetime is null and status=1<if test='brand &gt; 0'>and brand_id=#{brand}</if> order by createtime desc</script>"}) List<Map<String,Object>> platformCars(@Param("brand") long brand);
  @Select("select mc.id,mc.platform_car_id,mc.intro,mc.images,mc.cash_price,mc.month_price,mc.day_price,mc.hour_price,mc.total_stock,mc.stock,p.brand_id,p.specification from ymcx_merchant_car mc join ymcx_platform_car p on p.id=mc.platform_car_id and p.deletetime is null where mc.id=#{id} and mc.merchant_id=#{merchantId} and mc.is_delete=1 and mc.deletetime is null") Map<String,Object> car(@Param("id") long id,@Param("merchantId") long merchantId);
  @Select("select count(*) from ymcx_merchant_car where merchant_id=#{merchantId} and platform_car_id=#{platformId} and is_delete=1 and deletetime is null and id<>#{excludeId}") int duplicateCar(@Param("merchantId") long merchantId,@Param("platformId") long platformId,@Param("excludeId") long excludeId);
  @Select("select total_stock,stock from ymcx_merchant_car where id=#{id} and merchant_id=#{merchantId} and is_delete=1 and deletetime is null for update") Map<String,Object> lockCar(@Param("id") long id,@Param("merchantId") long merchantId);
  @Select("select status from ymcx_merchant_car where id=#{id} and merchant_id=#{merchantId} and is_delete=1 and deletetime is null") Integer carStatus(@Param("id") long id,@Param("merchantId") long merchantId);
  @Select("select count(*) from ymcx_merchant_cash where merchant_id=#{id} and is_delete=1 and deletetime is null") int cashCount(@Param("id") long id);
  @Select("select id,amount,status,createtime from ymcx_merchant_cash where merchant_id=#{id} and is_delete=1 and deletetime is null order by createtime desc limit #{limit} offset #{offset}") List<Map<String,Object>> cashRows(@Param("id") long id,@Param("limit") long limit,@Param("offset") long offset);
  @Update({"<script>update ymcx_merchant set updatetime=#{now}","<if test='v.containsKey(\"name\")'>,name=#{v.name}</if><if test='v.containsKey(\"avatar\")'>,avatar=#{v.avatar}</if><if test='v.containsKey(\"nickname\")'>,nickname=#{v.nickname}</if><if test='v.containsKey(\"image\")'>,image=#{v.image}</if><if test='v.containsKey(\"mobile\")'>,mobile=#{v.mobile}</if><if test='v.containsKey(\"business\")'>,business=#{v.business}</if><if test='v.containsKey(\"administrative\")'>,administrative=#{v.administrative}</if><if test='v.containsKey(\"address\")'>,address=#{v.address}</if><if test='v.containsKey(\"intro\")'>,intro=#{v.intro}</if><if test='v.containsKey(\"pick_type\")'>,pick_type=#{v.pick_type}</if><if test='v.containsKey(\"car_num\")'>,car_num=#{v.car_num}</if><if test='v.containsKey(\"min_price\")'>,min_price=#{v.min_price}</if><if test='v.containsKey(\"lat\")'>,lat=#{v.lat}</if><if test='v.containsKey(\"lng\")'>,lng=#{v.lng}</if><if test='v.containsKey(\"qrimage\")'>,qrimage=#{v.qrimage}</if>","where id=#{id} and is_delete=1 and deletetime is null</script>"}) int updateProfile(@Param("id") long id,@Param("v") Map<String,Object> values,@Param("now") long now);
  @Insert("insert into ymcx_merchant_car(platform_car_id,merchant_id,intro,images,cash_price,month_price,day_price,hour_price,total_stock,stock,status,is_delete,createtime,updatetime) values(#{platform},#{merchant},#{intro},#{images},#{cash},#{month},#{day},#{hour},#{total},#{total},1,1,#{now},#{now})") int insertCar(@Param("merchant") long merchant,@Param("platform") long platform,@Param("intro") String intro,@Param("images") String images,@Param("cash") BigDecimal cash,@Param("month") BigDecimal month,@Param("day") BigDecimal day,@Param("hour") BigDecimal hour,@Param("total") int total,@Param("now") long now);
  @Update("update ymcx_merchant_car set platform_car_id=#{platform},intro=#{intro},images=#{images},cash_price=#{cash},month_price=#{month},day_price=#{day},hour_price=#{hour},total_stock=#{total},stock=#{stock},updatetime=#{now} where id=#{id} and merchant_id=#{merchant} and deletetime is null") int updateCar(@Param("id") long id,@Param("merchant") long merchant,@Param("platform") long platform,@Param("intro") String intro,@Param("images") String images,@Param("cash") BigDecimal cash,@Param("month") BigDecimal month,@Param("day") BigDecimal day,@Param("hour") BigDecimal hour,@Param("total") int total,@Param("stock") int stock,@Param("now") long now);
  @Update("update ymcx_merchant_car set status=#{status},updatetime=#{now} where id=#{id} and merchant_id=#{merchant} and is_delete=1 and deletetime is null") int updateCarStatus(@Param("id") long id,@Param("merchant") long merchant,@Param("status") int status,@Param("now") long now);
  @Update("update ymcx_merchant_car set is_delete=2,deletetime=#{now},updatetime=#{now} where id=#{id} and merchant_id=#{merchant} and is_delete=1 and deletetime is null") int deleteCar(@Param("id") long id,@Param("merchant") long merchant,@Param("now") long now);
  @Select("select money from ymcx_merchant where id=#{id} and deletetime is null for update") Map<String,Object> lockMerchantMoney(@Param("id") long id);
  @Select("select count(*) from ymcx_merchant_cash where out_trade_no=#{number} and deletetime is null") int cashNumberCount(@Param("number") String number);
  @Insert("insert into ymcx_merchant_cash(out_trade_no,merchant_id,amount,status,createtime,updatetime,is_delete) values(#{v.out_trade_no},#{v.merchant_id},#{v.amount},1,#{v.now},#{v.now},1)") @Options(useGeneratedKeys=true,keyProperty="v.id") int insertCash(@Param("v") Map<String,Object> values);
  @Update("update ymcx_merchant set money=#{money},updatetime=#{now} where id=#{id} and deletetime is null") int updateMerchantMoney(@Param("id") long id,@Param("money") BigDecimal money,@Param("now") long now);
  @Insert("insert into ymcx_merchant_money_log(merchant_id,money,`before`,`after`,type,memo,createtime,updatetime,is_delete,order_id) values(#{merchant},#{amount},#{before},#{after},2,'提现申请扣减',#{now},#{now},1,#{cashId})") int insertCashLog(@Param("merchant") long merchant,@Param("amount") BigDecimal amount,@Param("before") BigDecimal before,@Param("after") BigDecimal after,@Param("now") long now,@Param("cashId") long cashId);
  @Select("select id,money,commission_normal_rate,commission_merchant_rate,commission_shop_rate from ymcx_merchant where id=#{id} and is_delete=1 and deletetime is null for update") Map<String,Object> lockSettlementMerchant(@Param("id") long id);
  @Select("select * from ymcx_order where merchant_id=#{merchantId} and number=#{number} and is_delete=1 for update") Map<String,Object> lockSettlementOrder(@Param("merchantId") long merchantId,@Param("number") String number);
  @Update("update ymcx_order set state=4,pick_state=2,refund_cash_price=#{refund},return_type=2,cash_state=if(cash_state=1,1,3),updatetime=#{now} where id=#{id}") int markAbnormalReturn(@Param("id") long id,@Param("refund") BigDecimal refund,@Param("now") long now);
  @Insert("insert into ymcx_platform_log(user_id,order_id,amount,type,log_note,user_type,createtime,is_delete) values(#{userId},#{orderId},#{amount},2,'租车押金退款',1,#{now},1)") int insertDepositRefund(@Param("userId") long userId,@Param("orderId") long orderId,@Param("amount") BigDecimal amount,@Param("now") long now);
  @Update("update ymcx_order set state=5,pick_state=3,return_type=1,refund_number=if(#{refund}>0,#{refundNo},refund_number),refund_cash_price=if(#{refund}>0,#{refund},refund_cash_price),last_all_money=if(#{refund}>0,#{last},last_all_money),cash_state=if(#{refund}>0 and cash_price>0 and cash_state<>1,3,cash_state),updatetime=#{now} where id=#{id}") int completeReturn(@Param("id") long id,@Param("refundNo") String refundNo,@Param("refund") BigDecimal refund,@Param("last") BigDecimal last,@Param("now") long now);
  @Update("update ymcx_merchant_car set stock=stock+1,updatetime=#{now} where id=#{id} and deletetime is null") int restoreStock(@Param("id") long id,@Param("now") long now);
  @Update("update ymcx_merchant set money=money+#{money},commission_money=commission_money+#{money},updatetime=#{now} where id=#{id} and deletetime is null") int addMerchantCommission(@Param("id") long id,@Param("money") BigDecimal money,@Param("now") long now);
  @Insert("insert into ymcx_merchant_money_log(merchant_id,money,`before`,`after`,type,money_type,memo,createtime,updatetime,is_delete,order_id) values(#{merchantId},#{money},#{before},#{after},1,#{moneyType},#{memo},#{now},#{now},1,#{orderId})") int insertMerchantCommission(@Param("merchantId") long merchantId,@Param("money") BigDecimal money,@Param("before") BigDecimal before,@Param("after") BigDecimal after,@Param("moneyType") int moneyType,@Param("memo") String memo,@Param("now") long now,@Param("orderId") long orderId);
  @Select("select id,money,commission_shop_rate from ymcx_shop where id=#{id} and is_delete=1 and deletetime is null for update") Map<String,Object> lockSettlementShop(@Param("id") long id);
  @Update("update ymcx_shop set money=money+#{money},commission_money=commission_money+#{money},updatetime=#{now} where id=#{id} and deletetime is null") int addShopCommission(@Param("id") long id,@Param("money") BigDecimal money,@Param("now") long now);
  @Insert("insert into ymcx_shop_money_log(shop_id,money,`before`,`after`,type,memo,createtime,updatetime,is_delete,order_id) values(#{shopId},#{money},#{before},#{after},1,'扫酒店码租车下单酒店获取佣金',#{now},#{now},1,#{orderId})") int insertShopCommission(@Param("shopId") long shopId,@Param("money") BigDecimal money,@Param("before") BigDecimal before,@Param("after") BigDecimal after,@Param("now") long now,@Param("orderId") long orderId);
  @Select("select id,value from ymcx_config where name='system_money' for update") Map<String,Object> lockSystemMoney();
  @Update("update ymcx_config set value=#{value} where id=#{id}") int updateSystemMoney(@Param("id") long id,@Param("value") String value);
  @Insert("insert into ymcx_system_money_log(money,`before`,`after`,type,memo,createtime,updatetime,is_delete,order_id) values(#{money},#{before},#{after},#{type},#{memo},#{now},#{now},1,#{orderId})") int insertSystemCommission(@Param("money") BigDecimal money,@Param("before") BigDecimal before,@Param("after") BigDecimal after,@Param("type") int type,@Param("memo") String memo,@Param("now") long now,@Param("orderId") long orderId);
}
